#!/usr/bin/env bash
# 전체 흐름 모의 실행 — 가짜 gh·claude·원격 저장소로 러너(bin/run.sh)를 실제로 돌린다.
#   사용: tests/sim/run_sim.sh <scenario.json> [--keep]   → 결과 요약 JSON 을 stdout 에 쓴다 (outcome, stages, prs, releases, gh 호출)
# 실제 상태·로그·데이터·잠금 파일은 건드리지 않는다 (AIDEV_STATE/LOGS/DATA/OWNER/WT_BASE 를 임시 경로로).
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; REPO_DIR="$(cd "$HERE/../.." && pwd)"
SCN=${1:?scenario.json}; KEEP=${2:-}
T=$(mktemp -d /tmp/aidev-sim.XXXXXX)
export AIDEV_SIM="$T/sim" AIDEV_STATE="$T/state" AIDEV_LOGS="$T/logs" AIDEV_DATA="$T/data" AIDEV_OWNER="$T/run.owner" WT_BASE="$T/wt" ROOT="$T/projects" HOME_REAL="$HOME"
mkdir -p "$AIDEV_SIM" "$AIDEV_STATE" "$AIDEV_LOGS" "$AIDEV_DATA" "$WT_BASE" "$ROOT"
cp "$REPO_DIR/state/default.policy.json" "$REPO_DIR/state/default.guard" "$AIDEV_STATE/"
[ -f "$REPO_DIR/state/caps.env" ] && cp "$REPO_DIR/state/caps.env" "$AIDEV_STATE/"
# 모의 프로젝트: bare 원격 + 작업 클론
proj=simproj; origin="$T/origin.git"; git init -q --bare "$origin"
git --git-dir="$origin" symbolic-ref HEAD refs/heads/main   # bare 의 기본 HEAD 가 master 라 clone 이 체크아웃하지 못해 머지가 조용히 실패했다(2026-09-08)
git init -q -b main "$ROOT/$proj"; ( cd "$ROOT/$proj" && echo "# sim" > README.md && printf 'v0.0.1\n' > VERSION && git add -A && git -c user.name=sim -c user.email=sim@x commit -qm "init" && git remote add origin "$origin" && git push -q -u origin main )
git -C "$ROOT/$proj" tag -a v0.0.1 -m v0.0.1; git -C "$ROOT/$proj" push -q origin v0.0.1
# 시나리오 → 모의 도구가 읽을 위치 (gh 는 AIDEV_SIM, claude 는 STATE)
jq --arg o "$origin" --arg p "$ROOT/$proj" '. + {origin:$o, project_repo:$p}' "$SCN" > "$AIDEV_SIM/scenario.json"; cp "$AIDEV_SIM/scenario.json" "$AIDEV_STATE/scenario.json"
# 프로젝트 정책: 러너 검증은 시나리오가 정한 명령(기본 true)
jq -n --argjson v "$(jq -c '.verify // ["true"]' "$SCN")" --argjson nc "$(jq -c '.allow_merge_without_ci // false' "$SCN")" --arg au "$(jq -r '.autonomy // "release"' "$SCN")" \
   '{verify:$v, allow_merge_without_ci:$nc, autonomy:$au}' > "$AIDEV_STATE/$proj.policy.json"
# 이전 릴리즈(자산 포함)를 원격에 있는 것처럼
for a in $(jq -r '.prev_release_assets[]? // empty' "$SCN"); do mkdir -p "$AIDEV_SIM/releases/v0.0.1/assets"; head -c 2048 /dev/urandom > "$AIDEV_SIM/releases/v0.0.1/assets/$a"; done
[ -d "$AIDEV_SIM/releases/v0.0.1" ] && jq -n '{tagName:"v0.0.1",name:"v0.0.1",publishedAt:"2026-01-01T00:00:00+09:00",isPrerelease:false,body:""}' > "$AIDEV_SIM/releases/v0.0.1/meta.json"
[ "$(jq -r '.tag_exists // false' "$SCN")" = true ] && { git -C "$ROOT/$proj" tag -a "$(jq -r '.release.tag // "v0.0.2"' "$SCN")" -m x; git -C "$ROOT/$proj" push -q origin "$(jq -r '.release.tag // "v0.0.2"' "$SCN")"; }
[ "$(jq -r '.experiment // empty' "$SCN")" != "" ] && jq '.experiment' "$SCN" > "$AIDEV_STATE/experiment.json"
for st in $(jq -r '.stops[]? // empty' "$SCN"); do touch "$AIDEV_STATE/STOP$( [ "$st" = all ] && echo "" || echo "-$st")"; done
[ "$(jq -r '.duplicate_pr // false' "$SCN")" = true ] && export AIDEV_SIM_DUP=1
touch "$AIDEV_DATA/runs.jsonl" "$AIDEV_DATA/usage.jsonl"
export PATH="$HERE/bin:$PATH"
extra=$(jq -r '.args // ""' "$SCN")
# 승인 스윕·수동 큐 등은 --project 로 건너뛴다; 시간 대기는 짧게
export T_IMPROVE=120 T_REVIEW=60 T_RELEASE=120 T_ASSETS=120 CI_POLL=1 CI_MAX=4 REL_MAX=2 RETRY_DELAYS="1 1 1"
( cd "$REPO_DIR" && bash bin/run.sh --project "$proj" --no-sync $extra ) > "$T/runner.out" 2>&1
rc=$?
{ [ -s "$AIDEV_DATA/runs.jsonl" ] && tail -1 "$AIDEV_DATA/runs.jsonl" || echo '{}'; } | jq -c --arg t "$T" --argjson rc "$rc" \
  --argjson prs "$(for f in "$AIDEV_SIM"/prs/*.json; do [ -f "$f" ] && jq -c '{url,state,head}' "$f"; done | jq -s '.')" \
  --argjson rels "$(for f in "$AIDEV_SIM"/releases/*/meta.json; do [ -f "$f" ] && jq -c --arg d "$(dirname "$f")/assets" '{tag:.tagName, assets:[]}' "$f" | jq -c --arg d "$(dirname "$f")/assets" '.assets=[($d|.)]' ; done | jq -s '.')" \
  --arg tags "$(git --git-dir="$origin" tag | tr '\n' ' ')" --arg gh "$(grep -c . "$AIDEV_SIM/log/gh.log" 2>/dev/null || echo 0)" \
  '{rc:$rc, outcome, result, arm, stages:((.stages // {})|map_values(.state)), prs:$prs, releases:$rels, remote_tags:$tags, gh_calls:($gh|tonumber), tmp:$t}'
for r in "$AIDEV_SIM"/releases/*/assets; do [ -d "$r" ] && printf '{"release_assets":"%s","names":"%s"}\n' "$(basename "$(dirname "$r")")" "$(ls "$r" | tr '\n' ' ')"; done
[ -n "$KEEP" ] || rm -rf "$T"
exit 0
import { defineConfig, loadEnv } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, process.cwd(), 'ADMIN_V2_')
  const proxyTarget = env.ADMIN_V2_DEV_PROXY_TARGET

  return {
    base: './',
    plugins: [vue()],
    resolve: {
      alias: {
        '@': new URL('./src', import.meta.url).pathname,
      },
    },
    server: {
      host: '0.0.0.0',
      port: 8090,
      strictPort: true,
      proxy: proxyTarget
        ? {
            '/api': {
              target: proxyTarget,
              changeOrigin: true,
              secure: false,
              rewrite: (path) => path.replace(/^\/api/, ''),
            },
          }
        : undefined,
    },
    preview: {
      port: 8091,
      strictPort: true,
    },
    build: {
      outDir: 'dist',
      emptyOutDir: true,
      sourcemap: false,
      reportCompressedSize: true,
    },
  }
})
import { readonly, ref } from 'vue'

export type NotificationTone = 'success' | 'error' | 'info'

export interface NotificationItem {
  id: number
  message: string
  tone: NotificationTone
}

const items = ref<NotificationItem[]>([])
let sequence = 0

function remove(id: number) {
  items.value = items.value.filter((item) => item.id !== id)
}

function notify(message: string, tone: NotificationTone = 'info') {
  const id = ++sequence
  items.value.push({ id, message, tone })
  window.setTimeout(() => remove(id), 4500)
}

export function useNotifications() {
  return {
    items: readonly(items),
    notify,
    remove,
  }
}
})

function hydrate(value: AdvancedPolicySnapshot) {
  snapshot.value = value
  form.deleteTerm = Number(value.deleteTerm || 30)
  const adminLimit = value.notebookLimits.find((item) => item.group === 'admin')?.limit ?? -1
  const userLimit = value.notebookLimits.find((item) => item.group === 'user')?.limit ?? 5
  form.adminUnlimited = adminLimit < 0
  form.userUnlimited = userLimit < 0
  form.adminLimit = adminLimit > 0 ? adminLimit : 10
  form.userLimit = userLimit > 0 ? userLimit : 5
}

async function load() {
  const ticket = policyRequest.start()
  loading.value = true
  error.value = ''
  try {
    const result = await getAdvancedPolicySnapshot()
    if (!ticket.isLatest()) return
    hydrate(result)
  } catch (reason) {
    if (!ticket.isLatest()) return
    error.value = reason instanceof Error ? reason.message : '세부 정책을 불러오지 못했습니다.'
  } finally {
    if (ticket.isLatest()) loading.value = false
  }
}

async function runSave(key: string, action: () => Promise<unknown>, message: string) {
  if (!writesEnabled.value || saving.value) return false
  saving.value = key
  try {
    await action()
    notify(message, 'success')
    await load()
    return true
  } catch (reason) {
    notify(reason instanceof Error ? reason.message : '정책을 변경하지 못했습니다.', 'error')
    return false
  } finally {
    saving.value = ''
  }
}

async function addBannedWord() {
  const word = form.bannedWord.trim()
  if (word.length < 2 || word.length > 10) {
    notify('금칙어는 2~10자로 입력하십시오.', 'error')
    const lastPage = lastPageWhenOutOfRange(result)
    if (lastPage) return await loadSharedApps(lastPage)
  } catch (reason) {
    if (!ticket.isLatest()) return
    tabError.shared = reason instanceof Error ? reason.message : '공유 앱 목록을 불러오지 못했습니다.'
  } finally {
    if (ticket.isLatest()) tabLoading.shared = false
  }
}

function changeTab(tab: CatalogTab) {
  activeTab.value = tab
  if (tab === 'library' && !tabLoaded.library && !tabLoading.library) void loadLibrary()
  if (tab === 'shared' && sharedFilters.userId && !tabLoaded.shared && !tabLoading.shared) void loadSharedApps()
}

// 사용자·부서 화면은 같은 경로의 query만 바꿔 다른 사용자의 공유 앱으로 이동한다.
// 그때 화면을 다시 mount하지 않으므로 query를 적용하는 일은 진입과 query 변경에서 같아야 한다.
function applyRouteQuery() {
  const tab: CatalogTab = queryValue('tab') === 'shared' ? 'shared' : 'library'
  activeTab.value = tab
  sharedFilters.userId = queryValue('userId')
  sharedFilters.searchKey = ''
  tabError.library = ''
  tabError.shared = ''
  // 비활성 탭의 늦은 응답도 이전 조건의 결과·완료 상태를 되살리지 못하게 한다.
  sharedRequest.invalidate()
  tabLoading.shared = false
  sharedApps.value = { items: [], pageNum: 1, pageSize: sharedApps.value.pageSize, totalCount: 0 }
  tabLoaded.shared = false
  closeLibraryDetail()
  if (tab === 'shared') void loadSharedApps()
  else void loadLibrary()
}

useRouteQuerySync(['tab', 'userId'], applyRouteQuery)
</script>

<template>
  <section>
    <PageHeader eyebrow="Content operations" title="콘텐츠 운영" description="사용자 포털 자료실과 사용자별 최근 공유 앱을 기존 API로 교차 조회합니다.">
      <template #actions>
        <span class="badge badge--blue">READ ONLY</span>
        <button class="button button--secondary" type="button" :disabled="loading" @click="activeTab === 'library' ? loadLibrary(library.pageNum) : loadSharedApps(sharedApps.pageNum)">
          <AppIcon name="refresh" :size="17" /> 새로고침
        </button>
      </template>
    </PageHeader>

    <InlineNotice tone="info" title="운영 영향이 없는 조회 기능부터 제공합니다.">
      게시물과 앱의 수정·삭제·공유 해제는 backend 관리자 RBAC와 감사 로그가 적용된 뒤 활성화합니다. 자료실 본문은 스크립트가 실행되지 않는 일반 텍스트로 표시합니다.
    </InlineNotice>
    <InlineNotice v-if="error" tone="danger" title="콘텐츠 조회 실패">{{ error }}</InlineNotice>

    <div class="tabs" role="tablist" aria-label="콘텐츠 운영">
      <button type="button" role="tab" :aria-selected="activeTab === 'library'" :class="{ 'is-active': activeTab === 'library' }" @click="changeTab('library')">자료실</button>
